1210: inline static void bit_write(int port)
1211: {
1212:     CLOCK write_time;
1213:     uint8_t write_gap;
1214: 
1215:     write_time = maincpu_clk - last_write_clk[port];
1216:     DBG(("bit_write last_write_clk: 0x%"PRIx64" maincpu_clk: 0x%"PRIx64" write_time: 0x%"PRIx64" tap: 0x%"PRIx64"",
1217:          last_write_clk[port], maincpu_clk, write_time,
1218:          (write_time / (CLOCK)8) > 0xff ? write_time : (write_time / (CLOCK)8)));
1219:     last_write_clk[port] = maincpu_clk;
1220: 
1221:     /* C16 TAPs use half the machine clock as base cycle */
1222:     if (machine_class == VICE_MACHINE_PLUS4) {
1223:         /* FIXME: we might also need to compensate for the remainder of this / 2 */
1224:         write_time = write_time / 2;
1225:     }
1226: 
1227:     if (write_time < (CLOCK)7) {
1228:         /* make sure the remainder does not get lost */
1229:         last_write_clk[port] -= (write_time % (CLOCK)8);
1230:         return;
1231:     }
1232: 
1233:     if (write_time < (CLOCK)(255 * 8 + 7)) {
1234:         /* this is a normal short/one byte gap */
1235:         write_gap = (write_time / (CLOCK)8);
1236:         /* make sure the remainder does not get lost */
1237:         last_write_clk[port] -= (write_time % (CLOCK)8);
1238:         if (fwrite(&write_gap, 1, 1, current_image[port]->fd) < 1) {
1239:             log_error(datasette_log, "datasette bit_write failed (stopping tape).");
1240:             datasette_control(port, DATASETTE_CONTROL_STOP);
1241:             return;
1242:         }
1243:         DBG(("bit_write v0 value 0x%02x at position 0x%04x",
1244:              write_gap, (unsigned int)current_image[port]->current_file_seek_position));
1245:         current_image[port]->current_file_seek_position++;
1246:     } else {
1247:         /* this is a long gap, v0 tap only stores a zero for this, in v1 the zero
1248:            is followed by the exact length - so write the zero first */
1249:         write_gap = 0;
1250:         if (fwrite(&write_gap, 1, 1, current_image[port]->fd) != 1) {
1251:             log_error(datasette_log, "datasette bit_write failed (stopping tape).");
1252:             datasette_control(port, DATASETTE_CONTROL_STOP);
1253:             return;
1254:         }
1255:         current_image[port]->current_file_seek_position++;
1256:         /* in v1/v2 .tap the next 3 bytes are the exact length of the gap in cycles */
1257:         if (current_image[port]->version >= 1) {
1258:             uint8_t long_gap[3];
1259:             int bytes_written;
1260:             long_gap[0] = (uint8_t)(write_time & 0xff);
1261:             long_gap[1] = (uint8_t)((write_time >> 8) & 0xff);
1262:             long_gap[2] = (uint8_t)((write_time >> 16) & 0xff);
1263:             write_time &= 0xffffff;
1264:             bytes_written = (int)fwrite(long_gap, 1, 3, current_image[port]->fd);
1265:             DBG(("bit_write v1 gap 0x%"PRIx64" at position 0x%04x",
1266:                 write_time, (unsigned int)current_image[port]->current_file_seek_position - 1));
1267:             current_image[port]->current_file_seek_position += bytes_written;
1268:             if (bytes_written < 3) {
1269:                 log_error(datasette_log, "datasette bit_write failed (stopping tape).");
1270:                 datasette_control(port, DATASETTE_CONTROL_STOP);
1271:                 return;
1272:             }
1273:         }
1274:     }
1275:     /* adjust file size */
1276:     if (current_image[port]->size < current_image[port]->current_file_seek_position) {
1277:         current_image[port]->size = current_image[port]->current_file_seek_position;
1278:     }
1279: 
1280:     current_image[port]->cycle_counter += write_time / 8;
1281: 
1282:     /* Correct for C16 TAPs so the counter is the same during record/play */
1283:     if (machine_class == VICE_MACHINE_PLUS4) {
1284:         current_image[port]->cycle_counter += write_time / 8;
1285:     }
1286: 
1287:     if (current_image[port]->cycle_counter_total < current_image[port]->cycle_counter) {
1288:         current_image[port]->cycle_counter_total = current_image[port]->cycle_counter;
1289:     }
1290:     current_image[port]->has_changed = 1;
1291:     datasette_update_ui_counter(port);
1292: }
