254:     ///
255:     /// Motor ramp: when MotorEnabled is true, tracks the 32,000-cycle ramp.
256:     /// The ramp only activates after the first Tick() call with motor on;
257:     /// before any Tick(), TryReadNextPulse delivers pulses immediately
258:     /// (backward-compatible with tests that manage timing externally).
259:     /// After the ramp completes, pulses are delivered. Motor off resets
260:     /// the ramp so a full new spin-up is required on next motor-on.
261:     /// VICE datasette/datasette.c:62 MOTOR_DELAY=32000,
262:     /// datasette.c:1196 motor_stop_clk reset on motor off.
263:     /// </summary>
264:     public void Tick()
265:     {
266:         if (MotorEnabled)
267:         {
268:             if (!_motorRampStarted)
269:             {
270:                 // First Tick with motor on: begin the ramp countdown.
271:                 _motorRampStarted = true;
272:                 _motorRampComplete = false;
273:                 _motorRampCounter = 0;
274:             }
275:             if (!_motorRampComplete)
276:             {
277:                 _motorRampCounter++;
278:                 if (_motorRampCounter >= MotorRampCycles)
279:                     _motorRampComplete = true;
280:             }
281:         }
282:         else
283:         {
284:             // Motor off: reset ramp so a new spin-up is required.
285:             _motorRampCounter = 0;
286:             _motorRampComplete = false;
287:             _motorRampStarted = false;
288:         }
289:     }
