1320:     /// <summary>
1321:     /// CPU-visible $0001. VICE c64pla.c forces bit 5 to 0 whenever it is an
1322:     /// input, and clears bit 4 when the datasette sense line is active and
1323:     /// that bit is an input. tape_sense active matches SenseLine low.
1324:     /// </summary>
1325:     private byte ReadVisibleProcessorPort()
1326:     {
1327:         var value = _pla.Read(0x0001);
1328:         var direction = _pla.DataDirection;
1329:         if ((direction & 0x20) == 0)
1330:             value = (byte)(value & 0xDF);
1331: 
1332:         if (_datasette is not null && !_datasette.SenseLine && (direction & 0x10) == 0)
1333:             value = (byte)(value & 0xEF);
1334: 
1335:         return value;
1336:     }

94:     /// change.
95:     /// </summary>
96:     public void Tick()
97:     {
98:         // If no pulse is pending, try to pull one. The datasette gates
99:         // on HasTape + MotorEnabled + PlayPressed internally; a false
100:         // return means we just stay idle this cycle.
101:         if (!_havePendingPulse)
102:         {
103:             if (!_datasette.TryReadNextPulse(out var cycles))
104:                 return;
105: 
106:             _cyclesUntilNextPulse = cycles;
107:             _havePendingPulse = true;
108:         }
109: 
110:         // Count this cycle off the pulse interval. When the interval
111:         // elapses, the READ line transitions high-to-low and CIA1 FLAG
112:         // latches via TriggerFlagPin. The next pulse will be pulled on
113:         // a subsequent Tick (so a degenerate zero-length pulse doesn't
114:         // recurse and starve the rest of the system).
115:         _cyclesUntilNextPulse--;
116:         if (_cyclesUntilNextPulse > 0)
117:             return;
118: 
119:         _havePendingPulse = false;
120:         _cia1.TriggerFlagPin();
121:     }
122: }

